// Real server-backed identity. Guest mode never fabricates an account or a ranking.
let user=null,ui=null,writeTimer=null,authGeneration=0,recovering=false;
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function call(path,value){const controller=new AbortController(),t=setTimeout(()=>controller.abort(),7000);try{const res=await fetch('/api/'+path,{method:value?'POST':'GET',credentials:'same-origin',headers:value?{'Content-Type':'application/json'}:{},body:value?JSON.stringify(value):undefined,signal:controller.signal});const data=await res.json();if(!res.ok)throw Error(data.error||'目前無法完成，請稍後重試。');return data}catch(err){if(err.name==='AbortError')throw Error('連線逾時，請稍後重試。');throw err}finally{clearTimeout(t)}}
export function currentUser(){return user}
export async function configureAccounts(callbacks){ui=callbacks;const generation=authGeneration;try{const r=await call('auth/me');if(generation!==authGeneration)return;user=r.user||null;ui.changed?.(user);if(user)await recoverProgress()}catch{if(generation===authGeneration)user=null}}
async function recoverProgress(){const owner=user?.id,generation=authGeneration;if(!owner)return;recovering=true;try{const r=await call('progress');if(generation!==authGeneration||user?.id!==owner)return;if(r.progress){ui.setSave(r.progress);ui.changed?.(user)}else await uploadProgress()}catch(err){if(generation===authGeneration)ui.toast('帳號已登入，進度同步稍後重試。')}finally{if(generation===authGeneration)recovering=false}}
export function queueProgress(){if(!user||recovering)return;clearTimeout(writeTimer);const owner=user.id,generation=authGeneration,snapshot=structuredClone(ui.getSave());writeTimer=setTimeout(()=>{if(user?.id===owner&&authGeneration===generation)uploadProgress(snapshot).catch(()=>{})},1200)}
async function uploadProgress(snapshot){if(!user)return;const owner=user.id;await call('progress',{progress:snapshot||structuredClone(ui.getSave()),ownerId:owner})}
export async function uploadRun(run){if(!user)return;const generation=authGeneration,owner=user.id;try{await call('runs',{...run,ownerId:owner});if(generation===authGeneration&&user?.id===owner)await uploadProgress()}catch{if(generation===authGeneration)ui.toast('本機進度已保存；排行榜尚未同步，請保持連線後再挑戰。')}}
export function accountPage(){if(!ui)return;if(user){ui.shell(`${head('自己的 ID，自己的冒險。','登入狀態與紀錄會保存在伺服器，換裝置後也能找回。')}<div class="panel account-panel"><div class="account-avatar">🦊</div><div class="eyebrow">YOUR EXPLORER ID</div><h2>${e(user.nickname)}</h2><p>玩家 ID：<b>@${e(user.username)}</b></p><div class="stat-row"><span>年級分組</span><b>${gradeName(user.grade)}</b></div><div class="stat-row"><span>排行榜顯示</span><b>${user.public?'使用暱稱公開':'目前隱藏'}</b></div><p>排行榜只顯示選擇公開的玩家暱稱。單人榜累計每關最佳成績，重玩不會無限累加分數。</p><label class="settings-row"><span><b>讓我的暱稱出現在排行榜</b><small>不用真名，也不公開密碼與帳號認證資料。</small></span><input type="checkbox" id="public-rank" ${user.public?'checked':''}></label><p id="account-status" role="status" aria-live="polite"></p><button class="btn" id="sync-account">立即同步進度 ↻</button><button class="btn secondary" id="go-ranking">查看排行榜 →</button><button class="text-btn" id="logout-account" style="display:block;margin:22px auto 0">登出這個 ID</button></div>`);document.querySelector('#public-rank').onchange=async event=>{const checkbox=event.target,generation=authGeneration,owner=user.id;checkbox.disabled=true;try{const r=await call('auth/profile',{public:checkbox.checked});if(generation!==authGeneration||user?.id!==owner)return;user=r.user;ui.changed?.(user);if(document.querySelector('#account-status'))document.querySelector('#account-status').textContent='排行榜顯示偏好已儲存。'}catch(err){if(generation!==authGeneration)return;checkbox.checked=!checkbox.checked;if(document.querySelector('#account-status'))document.querySelector('#account-status').textContent=err.message}finally{checkbox.disabled=false}};document.querySelector('#sync-account').onclick=async()=>{const b=document.querySelector('#sync-account');b.disabled=true;try{await uploadProgress();ui.toast('進度已同步到你的 ID。')}catch(err){ui.toast(err.message)}finally{b.disabled=false}};document.querySelector('#go-ranking').onclick=()=>ui.navigate('ranks');document.querySelector('#logout-account').onclick=async()=>{const generation=++authGeneration;clearTimeout(writeTimer);recovering=false;try{await uploadProgress();await call('auth/logout',{});if(generation!==authGeneration)return;user=null;ui.setSave(null);ui.changed?.(null);accountPage();ui.toast('已登出，雲端紀錄會留在你的 ID 裡。')}catch(err){ui.toast('登出未完成：'+err.message)}};return}authPage(false)}
function head(title,description){return `<div class="page-title"><div><div class="eyebrow">A HOME FOR YOUR ADVENTURE</div><h1>${title}</h1><p>${description}</p></div></div>`}
function gradeName(grade){return ({'lower':'國小 1–3 年級','upper':'國小 4–6 年級','junior':'國中 1–3 年級'})[grade]||'未分組'}
function authPage(register){ui.shell(`${head(register?'給冒險，取一個自己的名字。':'歡迎回來，小小探險家。',register?'建立 ID，就能保存進度、參加排行榜。也可以繼續使用免登入的單人模式。':'使用玩家 ID 登入，繼續上一次的單字冒險。')}<form class="panel account-panel" id="auth-form"><div class="account-avatar">${register?'🌱':'🦊'}</div><div class="tabs"><button type="button" class="${!register?'active':''}" id="login-tab">登入 ID</button><button type="button" class="${register?'active':''}" id="register-tab">建立新 ID</button></div><label class="form-label" for="username">玩家 ID</label><input class="field" id="username" name="username" autocomplete="username" minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]{3,24}" required placeholder="3–24 個英文字母、數字或底線">${register?'<label class="form-label" for="nickname">遊戲暱稱（請勿用真實姓名）</label><input class="field" id="nickname" maxlength="20" required placeholder="例如：星星小狐狸"><label class="form-label" for="grade">年級分組</label><select class="field" id="grade"><option value="lower">國小 1–3 年級</option><option value="upper">國小 4–6 年級</option><option value="junior">國中 1–3 年級</option></select>':''}<label class="form-label" for="password">密碼</label><input class="field" type="password" id="password" name="password" autocomplete="${register?'new-password':'current-password'}" minlength="8" maxlength="128" required placeholder="至少 8 個字元">${register?'<label class="settings-row"><span><b>暱稱出現在公開排行榜</b><small>選填，之後可以隨時調整。</small></span><input type="checkbox" id="register-public"></label>':''}<p class="error" id="auth-error" role="alert"></p><button class="btn" type="submit" id="auth-submit">${register?'建立我的 ID':'登入，繼續冒險'} →</button><button class="btn secondary" type="button" id="guest-play">先用訪客模式遊玩</button><p style="font-size:10px">不需要填寫真名或信箱。請記住 ID 與密碼；目前尚未提供信箱驗證或忘記密碼找回功能。</p></form>`);document.querySelector('#login-tab').onclick=()=>authPage(false);document.querySelector('#register-tab').onclick=()=>authPage(true);document.querySelector('#guest-play').onclick=()=>ui.navigate('map');document.querySelector('#auth-form').onsubmit=async event=>{event.preventDefault();const generation=++authGeneration;clearTimeout(writeTimer);recovering=true;const button=document.querySelector('#auth-submit');button.disabled=true;document.querySelector('#auth-error').textContent='';try{const body={username:document.querySelector('#username').value.trim(),password:document.querySelector('#password').value};if(register)Object.assign(body,{nickname:document.querySelector('#nickname').value.trim(),grade:document.querySelector('#grade').value,public:document.querySelector('#register-public').checked});const r=await call('auth/'+(register?'register':'login'),body);if(generation!==authGeneration)return;user=r.user;if(register)await uploadProgress();else await recoverProgress();if(generation!==authGeneration)return;recovering=false;ui.changed?.(user);accountPage();ui.toast(register?'你的冒險 ID 已建立！':'歡迎回來，繼續冒險吧。')}catch(err){if(generation!==authGeneration)return;recovering=false;const error=document.querySelector('#auth-error');if(error)error.textContent=err.message;button.disabled=false}}}
